{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Ginsenoside Rg3, a closely related dammarane ginsenoside with the same C3 sophorose but lacking the C20 disaccharide, showed low oral bioavailability in humans; the query Rb1 is larger and more polar, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Hydroxypropyl-β-cyclodextrin, a highly polar high-molecular-weight carbohydrate, has an absolute oral bioavailability of less than 1% in humans, supporting low F for similarly large polar glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Glycyrrhizin, a triterpenoid diglucuronide, has an absolute oral bioavailability of approximately 0.25% in humans, supporting low F for large glycosylated triterpenoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Acarbose, a polar pseudo-tetrasaccharide, has an absolute oral bioavailability of <2% in humans, supporting low F for large highly polar saccharide-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Levovirin, a highly polar nucleoside, has an oral bioavailability of about 10% in humans, below the 20% threshold, supporting low F for polar high-TPSA molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues—closely related ginsenosides and other large polar glycosides—show low oral bioavailability (<20%, often <5%) in humans. The physicochemical prior also predicts poor absorption. Therefore the query is predicted to have low oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself; all evidence comes from analogues, though transfer scores are high.",
    "No data on possible gut-microbiota deglycosylation to a smaller absorbable aglycone, but that would not represent intact oral bioavailability of the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

